### Objective
Build a unified Vector Motion Hub in Flutter demonstrating the architectural distinctions between timeline-driven Lottie animations and state-machine-driven Rive interactive graphics. The hub provides an interactive dashboard with navigation cards directing learners to dedicated deep-dive sub-lessons for both technologies.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const VectorMotionHubApp());
}

class VectorMotionHubApp extends StatelessWidget {
  const VectorMotionHubApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Vector Motion Architecture',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.deepPurple,
        useMaterial3: true,
      ),
      home: const VectorHubScreen(),
    );
  }
}

class VectorHubScreen extends StatelessWidget {
  const VectorHubScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Vector Motion & Interactive Graphics'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20.0),
        children: [
          const _MotionOverviewBanner(),
          const SizedBox(height: 24),
          Text(
            'Dedicated Vector Animation Sub-Lessons',
            style: Theme.of(context).textTheme.titleMedium?.copyWith(
                  fontWeight: FontWeight.bold,
                ),
          ),
          const SizedBox(height: 12),
          _VectorNavCard(
            title: 'Rive: State Machines & Interactive Motion',
            subtitle:
                'Compact .riv binary runtime, state machines, runtime inputs, bone rigging, and real-time pointer tracking.',
            badgeText: 'STATE MACHINE DRIVEN',
            badgeColor: Colors.deepOrange,
            icon: Icons.animation_rounded,
            onTap: () {
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(
                  content: Text('Open Rive sub-lesson from the Explore Approaches menu!'),
                  behavior: SnackBarBehavior.floating,
                  duration: Duration(seconds: 2),
                ),
              );
            },
          ),
          const SizedBox(height: 14),
          _VectorNavCard(
            title: 'Lottie: After Effects Vector Keyframe Engine',
            subtitle:
                'JSON parsing, Bodymovin workflow, frame scrubbing with AnimationController, and asset caching.',
            badgeText: 'DESIGNER WORKFLOW',
            badgeColor: Colors.teal,
            icon: Icons.movie_filter_rounded,
            onTap: () {
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(
                  content: Text('Open Lottie sub-lesson from the Explore Approaches menu!'),
                  behavior: SnackBarBehavior.floating,
                  duration: Duration(seconds: 2),
                ),
              );
            },
          ),
          const SizedBox(height: 28),
          _buildGuidanceCard(colorScheme),
        ],
      ),
    );
  }

  Widget _buildGuidanceCard(ColorScheme colorScheme) {
    return Card(
      elevation: 0,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      color: colorScheme.surfaceContainerHighest,
      child: const Padding(
        padding: EdgeInsets.all(20.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Architectural Decision Framework',
              style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14),
            ),
            SizedBox(height: 10),
            Text(
              '• Choose Rive when: Building interactive UI elements that must respond dynamically to user input (e.g. an animated mascot that follows text input, gamified buttons, or interactive switches).\n\n'
              '• Choose Lottie when: Integrating pre-rendered designer animations exported from Adobe After Effects (e.g. celebratory confetti, splash screen brand reveals, or multi-step onboarding illustrations).\n\n'
              '• Choose CustomPainter: When motion is algorithmic or mathematically bound to live application data (e.g. stock price charts or audio equalizers).',
              style: TextStyle(fontSize: 12, height: 1.5, color: Colors.black87),
            ),
          ],
        ),
      ),
    );
  }
}

class _MotionOverviewBanner extends StatelessWidget {
  const _MotionOverviewBanner();

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Card(
      elevation: 0,
      color: colorScheme.surfaceContainerLow,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      child: Padding(
        padding: const EdgeInsets.all(20.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(Icons.auto_awesome_rounded, color: colorScheme.primary, size: 28),
                const SizedBox(width: 12),
                Text(
                  'Modern Vector Motion Systems',
                  style: Theme.of(context).textTheme.titleMedium?.copyWith(
                        fontWeight: FontWeight.bold,
                      ),
                ),
              ],
            ),
            const SizedBox(height: 10),
            const Text(
              'Vector motion bridges the gap between creative design and mobile engineering. '
              'By deploying resolution-independent vector runtimes, applications achieve fluid '
              '60/120 FPS animations with negligible asset footprints. Explore both Rive and Lottie '
              'to master the modern Flutter animation ecosystem.',
              style: TextStyle(height: 1.5, fontSize: 13, color: Colors.black87),
            ),
          ],
        ),
      ),
    );
  }
}

class _VectorNavCard extends StatelessWidget {
  final String title;
  final String subtitle;
  final String badgeText;
  final Color badgeColor;
  final IconData icon;
  final VoidCallback onTap;

  const _VectorNavCard({
    required this.title,
    required this.subtitle,
    required this.badgeText,
    required this.badgeColor,
    required this.icon,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 1.5,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(16),
        child: Padding(
          padding: const EdgeInsets.all(18.0),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              CircleAvatar(
                radius: 24,
                backgroundColor: badgeColor.withValues(alpha: 0.12),
                child: Icon(icon, color: badgeColor, size: 26),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            title,
                            style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 14),
                          ),
                        ),
                        Container(
                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                          decoration: BoxDecoration(
                            color: badgeColor.withValues(alpha: 0.12),
                            borderRadius: BorderRadius.circular(6),
                          ),
                          child: Text(
                            badgeText,
                            style: TextStyle(
                              fontSize: 9,
                              fontWeight: FontWeight.bold,
                              color: badgeColor,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 6),
                    Text(
                      subtitle,
                      style: const TextStyle(fontSize: 12, color: Colors.black54, height: 1.4),
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 8),
              const Icon(Icons.arrow_forward_ios, size: 14, color: Colors.grey),
            ],
          ),
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **High-Level Architectural Taxonomy**:
   The parent overview introduces the distinction between timeline-driven linear vector playback (Lottie) and real-time state machine reactive input runtimes (Rive).
2. **Interactive Explore Cards**:
   `_VectorNavCard` provides immediate visual cues for `rive.json` and `lottie.json`, inviting the learner to delve into dedicated deep-dive implementations via the interactive bottom sheet.
3. **Decision Criteria Guide**:
   `_buildGuidanceCard` outlines enterprise trade-offs regarding designer workflow friction, CPU parsing overhead, and real-time input coupling.
